private val cells = HashMap<Long, MutableList<Entity>>()
private fun key(cx: Int, cy: Int) = (cx.toLong() shl 32) xor (cy.toLong() and 0xffffffffL)

fun insert(e: Entity) { cells.getOrPut(key(cellX(e), cellY(e))) { mutableListOf() } += e }

fun near(x: Double, y: Double, r: Double): List<Entity> =
    (cellY(y - r)..cellY(y + r)).flatMap { cy ->
        (cellX(x - r)..cellX(x + r)).flatMap { cx -> cells[key(cx, cy)].orEmpty() }
    }.filter { it.distanceTo(x, y) <= r }
